actors.on_interact:
World.currentScene.closeUpOn("cowboy")
await Dialog.say("cowboy", "Howdddd is the weather?")
await Dialog.showChoices([
  new DialogChoice("Sunny", async () => {
    await Dialog.say("cowboy", "Really?")
    await Dialog.showChoices([
      new DialogChoice("Yeah, really...", async () => { }),
      new DialogChoice("No, not really...", async () => { })
    ])
  }), 
  new DialogChoice("Who are you?", async () => {
    await Dialog.say("cowboy", "I'm a cowboy, of course!")
  }, "asked_why"),
  new DialogChoice("Nevermind", async () => {
    await done()
  }),
])

done = async () => {
  await Dialog.say("cowboy", "Fine, be like that!")
  Dialog.end()
  World.currentScene.stopCloseUp("cowboy")
}
